import{neuralComposer,neuralFields}from'./music-neural.js';
import{QUICK_TRACKS,quickTrackSettings}from'./music-quick-presets.js';
import{composeSong}from'./music-song.js';
import{compileMusic,checkScore,writeMIDI,MUSIC_KEYS}from'./music-compose.js';
import{chooseQuickBank,fitQuickBank,quickROMBank}from'./music-quick-bank.js';
import{applyAftermathTreatment}from'./music-aftermath-treatment.js';
const newSeed=()=>{if(globalThis.crypto?.getRandomValues){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0];}return Math.floor(Math.random()*0x100000000);};
export function quickTrackWorkshop(api){
 const neural=api.neural||neuralComposer(),$=s=>document.querySelector(s),esc=api.esc,state={preset:'sunny-route',seed:newSeed(),energy:65,bank:'auto',busy:false,serial:0};
 function cancel(){state.serial++;neural.cancel();api.stop();}
 function open(preset=state.preset){
  cancel();if(!QUICK_TRACKS[preset])preset='sunny-route';state.preset=preset;const p=QUICK_TRACKS[preset],sources=api.tracks();state.energy=p.energy;
  api.modal('Quick Track',`<p>Pick a scene. Melody, chords, bass, accompaniment, instruments and song structure are configured together. Every take is an original arrangement.</p><div id="quickVibes" class="quick-vibes">${Object.entries(QUICK_TRACKS).map(([id,v])=>`<button type="button" data-quick-vibe="${id}" aria-pressed="${id===preset}"><b>${esc(v.name)}</b><small>${esc(v.scene)}</small></button>`).join('')}</div><p id="quickDescription" class="callout"></p><label>Track name<input id="quickName" maxlength="120" value="${esc(p.name+' theme')}"></label><label>Energy <output id="quickEnergyValue">${state.energy}</output><input id="quickEnergy" type="range" min="0" max="100" value="${state.energy}"></label><label>Atmosphere treatment<select id="quickTreatment"><option value="none">Original scene identity</option><option value="worn-subtle">Worn · preserve identity</option><option value="worn-route">Worn route · familiar but damaged</option><option value="worn-strong">Worn · damaged memory</option></select></label><p id="quickTreatmentHint" class="hint-line">A worn treatment keeps the lead melody recognizable while darkening harmony, thinning accompaniment, and creating more silence.</p>${neuralFields('quick')}<label>Sound palette<select id="quickBank"><option value="auto">Auto · prefer imported ROM instruments</option><option value="studio">Studio cartridge palette · original sounds</option>${sources.map(t=>`<option value="${esc(t.id)}">${esc(t.name)} — instruments</option>`).join('')}</select></label><p id="quickPaletteHint" class="hint-line"></p><details><summary>Length & repeatable settings</summary><div class="studio-grid"><label>Intro bars<input id="quickIntro" type="number" min="0" max="128" value="${p.introBars}"></label><label>Main theme bars<input id="quickVerse" type="number" min="1" max="128" value="${p.verseBars}"></label><label>Bridge bars<input id="quickBridge" type="number" min="1" max="128" value="${p.bridgeBars}"></label><label>Variation seed<input id="quickSeed" type="number" min="0" max="4294967295" value="${state.seed}"></label></div></details><label class="check"><input id="quickLoop" type="checkbox" ${p.loop===false?'':'checked'}> Loop after the intro</label><p id="quickSummary" role="status"></p><p id="quickReport" role="status"></p><div class="studio-actions"><button id="quickPreview" class="primary" type="button">▶ Make & preview</button><button id="quickAnother" type="button">Another take</button><button id="quickStop" type="button">■ Stop</button><button id="quickArrange" type="button">Edit arrangement & notes</button><button id="quickMIDI" type="button">Export MIDI</button></div><p class="hint-line">Imported ROM instruments usually give the closest match to that game’s sound. The Studio palette uses original synthesized samples. Familiar song melodies are not copied by these presets.</p>`,async()=>{if(state.busy)return false;state.busy=true;const job=++state.serial;try{const made=await build();if(job!==state.serial)return false;api.add(made.asset);api.openLibrary();api.toast('Quick Track saved. Assign it to a map or scene.');}catch(e){if(e.name==='AbortError')return false;throw e;}finally{state.busy=false;}},'Save track');
  $('#quickBank').value=sources.some(t=>t.id===state.bank)||['auto','studio'].includes(state.bank)?state.bank:'auto';
  const safe=fn=>async()=>{if(state.busy)return;state.busy=true;const job=++state.serial;try{await fn(job);}catch(e){if(e.name!=='AbortError')api.error(e);}finally{state.busy=false;}};
  function options(){return quickTrackSettings(state.preset,{seed:Number($('#quickSeed').value),energy:Number($('#quickEnergy').value),introBars:Number($('#quickIntro').value),verseBars:Number($('#quickVerse').value),bridgeBars:Number($('#quickBridge').value)});}
  function selectedBank(){const value=$('#quickBank').value;return value==='studio'?null:value==='auto'?chooseQuickBank(sources,state.preset):sources.find(t=>t.id===value)||null;}
  function describe(){const p=QUICK_TRACKS[state.preset],o=options(),bank=selectedBank(),t=$('#quickTreatment').value;$('#quickDescription').textContent=p.description;$('#quickEnergyValue').textContent=$('#quickEnergy').value;$('#quickSummary').textContent=`${MUSIC_KEYS[o.key]} ${o.scale} · ${o.tempo} BPM · ${o.introBars+o.verseBars+o.bridgeBars} bars · ${o.introBars?o.introBars+'-bar intro, then ':''}main theme → bridge`;$('#quickPaletteHint').textContent=bank?'Instruments: '+bank.name:$('#quickBank').value==='auto'?'The opened ROM will supply instruments automatically when compatible. Otherwise, the Studio cartridge palette is used.':'Original brass, flute, mallets, piano, strings, picked bass, guitar and bells.';$('#quickTreatmentHint').textContent=t==='none'?'The scene stays intact.':t==='worn-strong'?'Strong worn treatment: sparse, slowed, minor-coloured and deliberately damaged while the lead remains recognizable.':t==='worn-route'?'Route treatment: preserve the route’s contour, then add cold space, lonely bass and broken echoes.':'Subtle worn treatment: a darker arrangement with the source identity intact.';}
  async function build(){api.stop();const revision=state.serial,o=options(),engine=$('#quickEngine').value,treatment=$('#quickTreatment').value;let bank=selectedBank(),score=composeSong(o),warnings=[];if(engine!=='phrase')score=await neural.generate(score,{...o,engine,temperature:Number($('#quickTemperature').value),onProgress:message=>{if($('#quickReport'))$('#quickReport').textContent=message;}});if(treatment!=='none')score=applyAftermathTreatment(score,{mode:treatment,seed:o.seed});if(bank&&$('#quickBank').value==='auto'){try{fitQuickBank(score,bank.asset);}catch{bank=null;}}if(!bank&&$('#quickBank').value==='auto'&&api.session?.()){ $('#quickReport').textContent='Finding matching ROM instruments…';bank=await quickROMBank(api.session(),state.preset,score);if(!bank)warnings.push('No compatible ROM bank found; using the Studio cartridge palette.');}if(bank){const fitted=fitQuickBank(score,bank.asset);score=fitted.score;warnings.push(...fitted.warnings);}if(revision!==state.serial)throw Object.assign(Error('Generation stopped.'),{name:'AbortError'});const stats=checkScore(score),asset=compileMusic(score,{name:$('#quickName').value.trim()||QUICK_TRACKS[state.preset].name+' theme',loop:$('#quickLoop').checked,bankAsset:bank?.asset||null});asset.arrangement.quick={preset:state.preset,seed:o.seed,engine:score.composition.neural?.engine||'phrase',bankId:bank?.id||null,treatment:treatment==='none'?null:score.composition.treatment};$('#quickReport').textContent=(score.composition.neural?score.composition.neural.engine+' melody · ':'Phrase composer · ')+stats.parts+' parts · '+stats.notes+' notes · '+stats.peak+' peak voices'+(warnings.length?' · '+warnings.join(' '):'');return{asset,score,bank,warnings};}
  document.querySelectorAll('[data-quick-vibe]').forEach(button=>button.onclick=()=>{cancel();state.preset=button.dataset.quickVibe;const p=QUICK_TRACKS[state.preset];$('#quickName').value=p.name+' theme';$('#quickEnergy').value=p.energy;$('#quickIntro').value=p.introBars;$('#quickVerse').value=p.verseBars;$('#quickBridge').value=p.bridgeBars;$('#quickLoop').checked=p.loop!==false;$('#quickReport').textContent='';document.querySelectorAll('[data-quick-vibe]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));describe();});$('#quickEnergy').oninput=()=>{cancel();describe();};$('#quickBank').onchange=()=>{cancel();state.bank=$('#quickBank').value;describe();};$('#quickTreatment').onchange=()=>{cancel();describe();};for(const id of ['quickIntro','quickVerse','quickBridge','quickSeed'])$('#'+id).oninput=()=>{cancel();try{describe();}catch(e){$('#quickSummary').textContent=e.message;}};$('#quickPreview').onclick=safe(async job=>{const made=await build();if(job===state.serial)return api.play(made.asset);});$('#quickAnother').onclick=safe(async job=>{const previous=Number($('#quickSeed').value);state.seed=newSeed();if(state.seed===previous)state.seed=(previous+1)>>>0;$('#quickSeed').value=state.seed;describe();const made=await build();if(job===state.serial)return api.play(made.asset);});$('#quickStop').onclick=()=>{cancel();$('#quickReport').textContent='Stopped.';};$('#quickArrange').onclick=safe(async job=>{const made=await build();if(job!==state.serial)return;api.arrange({score:made.score,name:made.asset.name,bankId:made.bank?.id,bankAsset:made.bank?.asset,loop:$('#quickLoop').checked,warnings:made.warnings});});$('#quickMIDI').onclick=safe(async job=>{const made=await build();if(job!==state.serial)return;return api.save(new Blob([writeMIDI(made.score)],{type:'audio/midi'}),made.asset.name.replace(/[^a-z0-9]+/gi,'_')+'.mid');});const setEngine=()=>{cancel();const value=$('#quickEngine').value;$('#quickTemperature').disabled=value==='phrase';$('#quickEngineHint').textContent=value==='musigan'?'The contour stage runs locally.':value==='hybrid'?'Hybrid develops a connected, chord-aware Pokémon/GBA-style phrase.':value==='magenta'?'The melody stage develops phrases over the arrangement’s chords.':'The instant composer uses the scene style and learned phrase rules.';};$('#quickEngine').onchange=setEngine;$('#quickTemperature').oninput=()=>{cancel();$('#quickTemperatureValue').textContent=$('#quickTemperature').value;};document.querySelector('#dialog')?.addEventListener('close',cancel,{once:true});setEngine();describe();
 }
 return{state,open,cancel};
}
